package omlx

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"

	agentcore "github.com/DocumentDrivenDX/fizeau/internal/core"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/limits"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/openai"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/registry"
	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
)

const DefaultBaseURL = "http://localhost:1235/v1"

func init() {
	registry.Register(registry.Descriptor{
		Type: "omlx",
		Factory: func(in registry.Inputs) agentcore.Provider {
			return New(Config{
				BaseURL:      in.BaseURL,
				APIKey:       in.APIKey,
				Model:        in.Model,
				ModelPattern: in.ModelPattern,
				KnownModels:  in.KnownModels,
				Headers:      in.Headers,
				Reasoning:    in.Reasoning,
			})
		},
		DefaultBaseURL: DefaultBaseURL,
		DefaultPort:    1235,
	})
}

var ProtocolCapabilities = openai.ProtocolCapabilities{
	Tools:            true,
	Stream:           true,
	StructuredOutput: true,
	Thinking:         true,
	ThinkingFormat:   openai.ThinkingWireFormatQwen,
	// OMLX serves Qwen MLX variants exclusively, so an explicit reasoning
	// request against a non-Qwen model is a configuration bug worth failing
	// the request for. LM Studio hosts mixed families and keeps this false.
	StrictThinkingModelMatch: true,
}

type Config struct {
	BaseURL      string
	APIKey       string
	Model        string
	ModelPattern string
	KnownModels  map[string]string
	Headers      map[string]string
	Reasoning    reasoning.Reasoning
}

func New(cfg Config) *openai.Provider {
	baseURL := cfg.BaseURL
	if baseURL == "" {
		baseURL = DefaultBaseURL
	}
	return openai.New(openai.Config{
		BaseURL:        baseURL,
		APIKey:         cfg.APIKey,
		Model:          cfg.Model,
		ProviderName:   "omlx",
		ProviderSystem: "omlx",
		ModelPattern:   cfg.ModelPattern,
		KnownModels:    cfg.KnownModels,
		Headers:        cfg.Headers,
		Reasoning:      cfg.Reasoning,
		Capabilities:   &ProtocolCapabilities,
	})
}

func LookupModelLimits(ctx context.Context, baseURL, model string) limits.ModelLimits {
	base := strings.TrimRight(baseURL, "/")
	endpoint := base + "/models/status"

	var status struct {
		Models []struct {
			ID               string `json:"id"`
			MaxContextWindow int    `json:"max_context_window"`
			MaxTokens        int    `json:"max_tokens"`
		} `json:"models"`
	}
	if err := getAndDecode(ctx, 5*time.Second, endpoint, &status); err != nil {
		return limits.ModelLimits{}
	}

	for _, entry := range status.Models {
		if strings.EqualFold(entry.ID, model) {
			return limits.ModelLimits{
				ContextLength:       entry.MaxContextWindow,
				MaxCompletionTokens: entry.MaxTokens,
			}
		}
	}
	return limits.ModelLimits{}
}

func getAndDecode(ctx context.Context, timeout time.Duration, endpoint string, out any) error {
	reqCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	req, err := http.NewRequestWithContext(reqCtx, http.MethodGet, endpoint, nil)
	if err != nil {
		return err
	}
	req.Header.Set("Accept", "application/json")

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close() //nolint:errcheck

	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 256))
		return fmt.Errorf("HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}
	return json.NewDecoder(resp.Body).Decode(out)
}

package vllm

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"strings"

	"github.com/DocumentDrivenDX/fizeau/internal/provider/utilization"
)

// UtilizationProbe queries vLLM server-root observability endpoints and
// normalizes them into the shared endpoint utilization shape.
type UtilizationProbe struct {
	baseURL string
	client  *http.Client
	cache   utilization.Cache
}

// NewUtilizationProbe creates a probe for an OpenAI-compatible vLLM base URL.
func NewUtilizationProbe(baseURL string, client *http.Client) *UtilizationProbe {
	if client == nil {
		client = http.DefaultClient
	}
	return &UtilizationProbe{
		baseURL: baseURL,
		client:  client,
	}
}

// Probe fetches /metrics from the server root and returns a normalized sample.
// Failures return stale or unknown utilization instead of surfacing endpoint
// unavailability.
func (p *UtilizationProbe) Probe(ctx context.Context) utilization.EndpointUtilization {
	body, err := p.get(ctx, utilization.ServerRoot(p.baseURL)+"/metrics")
	if err != nil {
		if stale, ok := p.cache.Stale(); ok {
			return stale
		}
		return utilization.Unknown(utilization.SourceVLLMMetrics)
	}

	running, ok := utilization.ParsePrometheusMetricValue(body, "vllm:num_requests_running")
	if !ok {
		if stale, ok := p.cache.Stale(); ok {
			return stale
		}
		return utilization.Unknown(utilization.SourceVLLMMetrics)
	}
	waiting, ok := utilization.ParsePrometheusMetricValue(body, "vllm:num_requests_waiting")
	if !ok {
		if stale, ok := p.cache.Stale(); ok {
			return stale
		}
		return utilization.Unknown(utilization.SourceVLLMMetrics)
	}

	sample := utilization.EndpointUtilization{
		ActiveRequests: utilization.Int(int(running)),
		QueuedRequests: utilization.Int(int(waiting)),
		Source:         utilization.SourceVLLMMetrics,
	}
	if cacheUsage, ok := utilization.ParsePrometheusMetricValue(body, "vllm:kv_cache_usage_perc"); ok {
		sample.CacheUsage = utilization.Float64(cacheUsage)
	} else if cacheUsage, ok := utilization.ParsePrometheusMetricValue(body, "vllm:gpu_cache_usage_perc"); ok {
		sample.CacheUsage = utilization.Float64(cacheUsage)
	}
	return p.cache.Remember(sample)
}

func (p *UtilizationProbe) get(ctx context.Context, endpoint string) (string, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return "", err
	}
	resp, err := p.client.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 256))
		return "", fmt.Errorf("HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", err
	}
	return string(body), nil
}

package omlx

import (
	"context"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	agent "github.com/DocumentDrivenDX/fizeau/internal/core"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func omlxServer(modelID string, maxContext, maxTokens int) *httptest.Server {
	return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/v1/models/status" {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"models": []map[string]any{
				{
					"id":                 modelID,
					"max_context_window": maxContext,
					"max_tokens":         maxTokens,
				},
			},
		})
	}))
}

func TestLookupModelLimits(t *testing.T) {
	srv := omlxServer("Qwen3.5-27B-4bit", 262_144, 32_768)
	defer srv.Close()

	got := LookupModelLimits(context.Background(), srv.URL+"/v1", "Qwen3.5-27B-4bit")
	assert.Equal(t, 262_144, got.ContextLength)
	assert.Equal(t, 32_768, got.MaxCompletionTokens)
}

func TestLookupModelLimits_ModelMatchIsCaseInsensitive(t *testing.T) {
	srv := omlxServer("Qwen3.5-27B-4bit", 262_144, 32_768)
	defer srv.Close()

	got := LookupModelLimits(context.Background(), srv.URL+"/v1", "qwen3.5-27b-4bit")
	assert.Equal(t, 262_144, got.ContextLength)
}

func TestLookupModelLimits_UnknownModelReturnsZero(t *testing.T) {
	srv := omlxServer("foo-model", 262_144, 32_768)
	defer srv.Close()

	got := LookupModelLimits(context.Background(), srv.URL+"/v1", "bar-model")
	assert.Zero(t, got.ContextLength)
	assert.Zero(t, got.MaxCompletionTokens)
}

func TestProtocolCapabilities(t *testing.T) {
	p := New(Config{BaseURL: "http://localhost:1235/v1"})
	assert.True(t, p.SupportsTools())
	assert.True(t, p.SupportsStream())
	assert.True(t, p.SupportsStructuredOutput())
	assert.True(t, p.SupportsThinking())
}

func TestChatStream_SurvivesKeepAliveCommentFrames(t *testing.T) {
	frames := []string{
		": keep-alive\n\n",
		`data: {"id":"chatcmpl-1","model":"qwen3","choices":[{"index":0,"delta":{"role":"assistant"},"finish_reason":null}]}` + "\n\n",
		": keep-alive\n\n",
		`data: {"id":"chatcmpl-1","model":"qwen3","choices":[{"index":0,"delta":{"content":"warmup-done"},"finish_reason":null}]}` + "\n\n",
		`data: {"id":"chatcmpl-1","model":"qwen3","choices":[{"index":0,"delta":{},"finish_reason":"stop"}],"usage":{"prompt_tokens":12,"completion_tokens":5,"total_tokens":17}}` + "\n\n",
		"data: [DONE]\n\n",
	}
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/v1/chat/completions" {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "text/event-stream; charset=utf-8")
		flusher, _ := w.(http.Flusher)
		for _, frame := range frames {
			_, _ = io.WriteString(w, frame)
			if flusher != nil {
				flusher.Flush()
			}
			time.Sleep(time.Millisecond)
		}
	}))
	defer srv.Close()

	p := New(Config{
		BaseURL: srv.URL + "/v1",
		APIKey:  "test",
		Model:   "qwen3",
	})

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	ch, err := p.ChatStream(ctx, []agent.Message{
		{Role: agent.RoleUser, Content: "hello"},
	}, nil, agent.Options{})
	require.NoError(t, err)

	var content string
	var streamErr error
	for delta := range ch {
		if delta.Err != nil {
			streamErr = delta.Err
		}
		content += delta.Content
	}

	require.NoError(t, streamErr, "omlx keep-alive SSE comment frames must not corrupt stream parsing")
	assert.Contains(t, content, "warmup-done")
}

package llamaserver

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"

	"github.com/DocumentDrivenDX/fizeau/internal/provider/utilization"
)

// UtilizationProbe queries llama-server observability endpoints and
// normalizes them into the shared endpoint utilization shape.
type UtilizationProbe struct {
	baseURL string
	client  *http.Client
	cache   utilization.Cache
}

// NewUtilizationProbe creates a probe for an OpenAI-compatible llama-server
// base URL.
func NewUtilizationProbe(baseURL string, client *http.Client) *UtilizationProbe {
	if client == nil {
		client = http.DefaultClient
	}
	return &UtilizationProbe{
		baseURL: baseURL,
		client:  client,
	}
}

// Probe first tries /metrics on the server root and falls back to /slots when
// metrics are unavailable.
func (p *UtilizationProbe) Probe(ctx context.Context) utilization.EndpointUtilization {
	if sample, ok := p.probeMetrics(ctx); ok {
		return p.cache.Remember(sample)
	}
	if sample, ok := p.probeSlots(ctx); ok {
		return p.cache.Remember(sample)
	}
	if stale, ok := p.cache.Stale(); ok {
		return stale
	}
	return utilization.Unknown(utilization.SourceLlamaMetrics)
}

func (p *UtilizationProbe) probeMetrics(ctx context.Context) (utilization.EndpointUtilization, bool) {
	body, err := p.get(ctx, utilization.ServerRoot(p.baseURL)+"/metrics")
	if err != nil {
		return utilization.EndpointUtilization{}, false
	}

	processing, ok := utilization.ParsePrometheusMetricValue(body, "llamacpp:requests_processing")
	if !ok {
		return utilization.EndpointUtilization{}, false
	}
	deferred, ok := utilization.ParsePrometheusMetricValue(body, "llamacpp:requests_deferred")
	if !ok {
		return utilization.EndpointUtilization{}, false
	}

	sample := utilization.EndpointUtilization{
		ActiveRequests: utilization.Int(int(processing)),
		QueuedRequests: utilization.Int(int(deferred)),
		Source:         utilization.SourceLlamaMetrics,
	}
	if cacheUsage, ok := utilization.ParsePrometheusMetricValue(body, "llamacpp:kv_cache_usage_ratio"); ok {
		sample.CacheUsage = utilization.Float64(cacheUsage)
	}
	return sample, true
}

func (p *UtilizationProbe) probeSlots(ctx context.Context) (utilization.EndpointUtilization, bool) {
	body, err := p.get(ctx, utilization.ServerRoot(p.baseURL)+"/slots")
	if err != nil {
		return utilization.EndpointUtilization{}, false
	}

	var arrayPayload []map[string]any
	slots := 0
	processing := 0
	if err := json.Unmarshal([]byte(strings.TrimSpace(body)), &arrayPayload); err == nil {
		slots = len(arrayPayload)
		for _, slot := range arrayPayload {
			if isProcessing(slot) {
				processing++
			}
		}
		return p.slotSample(processing, slots), true
	}

	var objectPayload struct {
		Slots     []map[string]any `json:"slots"`
		SlotCount int              `json:"slot_count"`
	}
	if err := json.Unmarshal([]byte(strings.TrimSpace(body)), &objectPayload); err != nil {
		return utilization.EndpointUtilization{}, false
	}
	slots = objectPayload.SlotCount
	if slots == 0 {
		slots = len(objectPayload.Slots)
	}
	for _, slot := range objectPayload.Slots {
		if isProcessing(slot) {
			processing++
		}
	}
	return p.slotSample(processing, slots), true
}

func (p *UtilizationProbe) slotSample(processing, slots int) utilization.EndpointUtilization {
	sample := utilization.EndpointUtilization{
		ActiveRequests: utilization.Int(processing),
		Source:         utilization.SourceLlamaSlots,
	}
	if slots > 0 {
		sample.MaxConcurrency = utilization.Int(slots)
		occupancy := float64(processing) / float64(slots)
		sample.CacheUsage = utilization.Float64(occupancy)
	}
	return sample
}

func isProcessing(slot map[string]any) bool {
	processing, _ := slot["is_processing"].(bool)
	return processing
}

func (p *UtilizationProbe) get(ctx context.Context, endpoint string) (string, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return "", err
	}
	resp, err := p.client.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 256))
		return "", fmt.Errorf("HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", err
	}
	return string(body), nil
}

package utilization

import (
	"net/url"
	"strconv"
	"strings"
	"sync"
	"time"
)

// Source identifies the probe path that produced a utilization sample.
type Source string

const (
	SourceUnknown        Source = "unknown"
	SourceVLLMMetrics    Source = "vllm.metrics"
	SourceLlamaMetrics   Source = "llama-server.metrics"
	SourceLlamaSlots     Source = "llama-server.slots"
	SourceRapidMLXStatus Source = "rapid-mlx.status"
)

// Freshness describes whether a sample was observed just now, reused after a
// failed probe, or has no known prior observation.
type Freshness string

const (
	FreshnessFresh   Freshness = "fresh"
	FreshnessStale   Freshness = "stale"
	FreshnessUnknown Freshness = "unknown"
)

// EndpointUtilization is the normalized utilization shape shared by local
// provider probes.
type EndpointUtilization struct {
	ActiveRequests         *int
	QueuedRequests         *int
	CacheUsage             *float64
	MaxConcurrency         *int
	TotalPromptTokens      *int
	TotalCompletionTokens  *int
	CacheHitType           *string
	CachedTokens           *int
	GeneratedTokens        *int
	ActiveRequestPhase     *string
	TTFTSeconds            *float64
	TokensPerSecond        *float64
	MetalActiveMemoryBytes *int64
	MetalPeakMemoryBytes   *int64
	MetalCacheMemoryBytes  *int64
	Source                 Source
	Freshness              Freshness
	ObservedAt             time.Time
}

// Cache preserves the most recent successful sample so probe failures can
// return stale utilization instead of surfacing hard endpoint unavailability.
type Cache struct {
	mu   sync.Mutex
	last *EndpointUtilization
}

// Remember stores a fresh sample and returns a normalized copy with fresh
// freshness and an observed timestamp.
func (c *Cache) Remember(sample EndpointUtilization) EndpointUtilization {
	c.mu.Lock()
	defer c.mu.Unlock()

	now := time.Now().UTC()
	sample.Freshness = FreshnessFresh
	sample.ObservedAt = now
	stored := clone(sample)
	c.last = &stored
	return stored
}

// Stale returns the last successful sample marked stale. The boolean reports
// whether a previous sample existed.
func (c *Cache) Stale() (EndpointUtilization, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if c.last == nil {
		return EndpointUtilization{}, false
	}
	stale := clone(*c.last)
	stale.Freshness = FreshnessStale
	return stale, true
}

// Unknown returns a sample with unknown freshness and no numeric values.
func Unknown(source Source) EndpointUtilization {
	return EndpointUtilization{
		Source:    source,
		Freshness: FreshnessUnknown,
	}
}

// Int returns a pointer to v.
func Int(v int) *int {
	return &v
}

// Float64 returns a pointer to v.
func Float64(v float64) *float64 {
	return &v
}

// Int64 returns a pointer to v.
func Int64(v int64) *int64 {
	return &v
}

// String returns a pointer to v.
func String(v string) *string {
	return &v
}

// ServerRoot strips a trailing /v1 path component from an OpenAI-compatible
// base URL while preserving the scheme, host, and any prefix path.
func ServerRoot(baseURL string) string {
	trimmed := strings.TrimSpace(strings.TrimRight(baseURL, "/"))
	if trimmed == "" {
		return ""
	}

	parsed, err := url.Parse(trimmed)
	if err != nil {
		return strings.TrimSuffix(trimmed, "/v1")
	}

	parsed.Fragment = ""
	parsed.RawQuery = ""
	path := strings.TrimRight(parsed.Path, "/")
	if strings.HasSuffix(path, "/v1") {
		path = strings.TrimSuffix(path, "/v1")
	}
	parsed.Path = path
	return strings.TrimRight(parsed.String(), "/")
}

// ParsePrometheusMetricValue returns the first numeric value for metric from
// a Prometheus-style plaintext metrics body.
func ParsePrometheusMetricValue(body, metric string) (float64, bool) {
	for _, line := range strings.Split(body, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") || !strings.HasPrefix(line, metric) {
			continue
		}
		rest := strings.TrimSpace(strings.TrimPrefix(line, metric))
		if strings.HasPrefix(rest, "{") {
			if idx := strings.Index(rest, "}"); idx >= 0 {
				rest = strings.TrimSpace(rest[idx+1:])
			}
		}
		fields := strings.Fields(rest)
		if len(fields) == 0 {
			continue
		}
		val, err := strconv.ParseFloat(fields[0], 64)
		if err == nil {
			return val, true
		}
	}
	return 0, false
}

func clone(sample EndpointUtilization) EndpointUtilization {
	out := sample
	if sample.ActiveRequests != nil {
		out.ActiveRequests = Int(*sample.ActiveRequests)
	}
	if sample.QueuedRequests != nil {
		out.QueuedRequests = Int(*sample.QueuedRequests)
	}
	if sample.CacheUsage != nil {
		out.CacheUsage = Float64(*sample.CacheUsage)
	}
	if sample.MaxConcurrency != nil {
		out.MaxConcurrency = Int(*sample.MaxConcurrency)
	}
	if sample.TotalPromptTokens != nil {
		out.TotalPromptTokens = Int(*sample.TotalPromptTokens)
	}
	if sample.TotalCompletionTokens != nil {
		out.TotalCompletionTokens = Int(*sample.TotalCompletionTokens)
	}
	if sample.CacheHitType != nil {
		out.CacheHitType = String(*sample.CacheHitType)
	}
	if sample.CachedTokens != nil {
		out.CachedTokens = Int(*sample.CachedTokens)
	}
	if sample.GeneratedTokens != nil {
		out.GeneratedTokens = Int(*sample.GeneratedTokens)
	}
	if sample.ActiveRequestPhase != nil {
		out.ActiveRequestPhase = String(*sample.ActiveRequestPhase)
	}
	if sample.TTFTSeconds != nil {
		out.TTFTSeconds = Float64(*sample.TTFTSeconds)
	}
	if sample.TokensPerSecond != nil {
		out.TokensPerSecond = Float64(*sample.TokensPerSecond)
	}
	if sample.MetalActiveMemoryBytes != nil {
		out.MetalActiveMemoryBytes = Int64(*sample.MetalActiveMemoryBytes)
	}
	if sample.MetalPeakMemoryBytes != nil {
		out.MetalPeakMemoryBytes = Int64(*sample.MetalPeakMemoryBytes)
	}
	if sample.MetalCacheMemoryBytes != nil {
		out.MetalCacheMemoryBytes = Int64(*sample.MetalCacheMemoryBytes)
	}
	return out
}

package rapidmlx

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"strconv"
	"strings"

	"github.com/DocumentDrivenDX/fizeau/internal/provider/utilization"
)

// UtilizationProbe queries Rapid-MLX status endpoints and normalizes them into
// the shared endpoint utilization shape.
type UtilizationProbe struct {
	baseURL string
	client  *http.Client
	cache   utilization.Cache
}

// NewUtilizationProbe creates a probe for an OpenAI-compatible Rapid-MLX base
// URL.
func NewUtilizationProbe(baseURL string, client *http.Client) *UtilizationProbe {
	if client == nil {
		client = http.DefaultClient
	}
	return &UtilizationProbe{
		baseURL: baseURL,
		client:  client,
	}
}

// Probe fetches /v1/status from the server root and returns a normalized
// sample. Failures return stale or unknown utilization instead of surfacing
// endpoint unavailability.
func (p *UtilizationProbe) Probe(ctx context.Context) utilization.EndpointUtilization {
	snapshot, ok := p.probeStatus(ctx)
	if !ok {
		if stale, ok := p.cache.Stale(); ok {
			return stale
		}
		return utilization.Unknown(utilization.SourceRapidMLXStatus)
	}

	return p.cache.Remember(snapshot.normalize())
}

func (p *UtilizationProbe) probeStatus(ctx context.Context) (rapidMLXStatusSnapshot, bool) {
	body, err := p.get(ctx, utilization.ServerRoot(p.baseURL)+"/status")
	if err != nil {
		return rapidMLXStatusSnapshot{}, false
	}

	snapshot, err := parseRapidMLXStatus(body)
	if err != nil {
		return rapidMLXStatusSnapshot{}, false
	}
	return snapshot, true
}

func parseRapidMLXStatus(body string) (rapidMLXStatusSnapshot, error) {
	var raw any
	dec := json.NewDecoder(strings.NewReader(body))
	dec.UseNumber()
	if err := dec.Decode(&raw); err != nil {
		return rapidMLXStatusSnapshot{}, err
	}

	payload, ok := raw.(map[string]any)
	if !ok {
		return rapidMLXStatusSnapshot{}, errors.New("rapid-mlx status payload was not an object")
	}

	snapshot := rapidMLXStatusSnapshot{
		Raw: payload,
	}
	snapshot.NumRunning = firstInt(payload, "num_running", "running", "requests_running")
	snapshot.NumWaiting = firstInt(payload, "num_waiting", "waiting", "requests_waiting")
	snapshot.TotalPromptTokens = firstInt(payload, "total_prompt_tokens", "prompt_tokens", "prompt_tokens_total")
	snapshot.TotalCompletionTokens = firstInt(payload, "total_completion_tokens", "completion_tokens", "generated_tokens_total")
	snapshot.CacheUsage = firstFloat(payload, "cache_usage", "cache_pressure", "cache_usage_ratio")
	snapshot.CacheHitType = firstString(payload, "cache_hit_type", "cache_hit")
	snapshot.CachedTokens = firstIntPtr(payload, "cached_tokens", "cache_tokens")
	snapshot.GeneratedTokens = firstIntPtr(payload, "generated_tokens")
	snapshot.MetalActiveMemoryBytes = firstInt64(payload, "metal_active_memory_bytes", "metal_active_bytes", "active_memory_bytes")
	snapshot.MetalPeakMemoryBytes = firstInt64(payload, "metal_peak_memory_bytes", "metal_peak_bytes", "peak_memory_bytes")
	snapshot.MetalCacheMemoryBytes = firstInt64(payload, "metal_cache_memory_bytes", "metal_cache_bytes", "cache_memory_bytes")

	if metal, ok := firstMap(payload, "metal", "metal_memory", "metal_stats"); ok {
		if snapshot.MetalActiveMemoryBytes == nil {
			snapshot.MetalActiveMemoryBytes = firstInt64(metal, "active_bytes", "active_memory_bytes")
		}
		if snapshot.MetalPeakMemoryBytes == nil {
			snapshot.MetalPeakMemoryBytes = firstInt64(metal, "peak_bytes", "peak_memory_bytes")
		}
		if snapshot.MetalCacheMemoryBytes == nil {
			snapshot.MetalCacheMemoryBytes = firstInt64(metal, "cache_bytes", "cache_memory_bytes")
		}
	}

	if cache, ok := firstMap(payload, "cache", "cache_stats", "cache_state"); ok {
		if snapshot.CacheUsage == nil {
			snapshot.CacheUsage = firstFloat(cache, "usage", "pressure", "ratio")
		}
		if snapshot.CacheHitType == nil {
			snapshot.CacheHitType = firstString(cache, "hit_type", "cache_hit_type")
		}
		if snapshot.CachedTokens == nil {
			snapshot.CachedTokens = firstIntPtr(cache, "cached_tokens", "cache_tokens")
		}
		if snapshot.GeneratedTokens == nil {
			snapshot.GeneratedTokens = firstIntPtr(cache, "generated_tokens")
		}
	}

	if active, ok := firstSlice(payload, "active_requests", "requests", "active"); ok {
		snapshot.ActiveRequests = make([]rapidMLXRequestSnapshot, 0, len(active))
		for _, entry := range active {
			req, ok := entry.(map[string]any)
			if !ok {
				continue
			}
			item := rapidMLXRequestSnapshot{
				Phase:           firstString(req, "phase", "state"),
				CacheHitType:    firstString(req, "cache_hit_type", "cache_hit"),
				CachedTokens:    firstIntPtr(req, "cached_tokens", "cache_tokens"),
				GeneratedTokens: firstIntPtr(req, "generated_tokens"),
				TTFTSeconds:     firstFloat(req, "ttft_s", "ttft_seconds"),
				TokensPerSecond: firstFloat(req, "tokens_per_second", "tokens_per_sec"),
			}
			snapshot.ActiveRequests = append(snapshot.ActiveRequests, item)
		}
		if len(snapshot.ActiveRequests) > 0 {
			first := snapshot.ActiveRequests[0]
			snapshot.ActiveRequestPhase = first.Phase
			if snapshot.CacheHitType == nil {
				snapshot.CacheHitType = first.CacheHitType
			}
			if snapshot.CachedTokens == nil {
				snapshot.CachedTokens = first.CachedTokens
			}
			if snapshot.GeneratedTokens == nil {
				snapshot.GeneratedTokens = first.GeneratedTokens
			}
			if snapshot.TTFTSeconds == nil {
				snapshot.TTFTSeconds = first.TTFTSeconds
			}
			if snapshot.TokensPerSecond == nil {
				snapshot.TokensPerSecond = first.TokensPerSecond
			}
		}
	}

	if snapshot.CacheUsage == nil {
		switch {
		case snapshot.MetalActiveMemoryBytes != nil && snapshot.MetalPeakMemoryBytes != nil && *snapshot.MetalPeakMemoryBytes > 0:
			usage := float64(*snapshot.MetalActiveMemoryBytes) / float64(*snapshot.MetalPeakMemoryBytes)
			snapshot.CacheUsage = utilization.Float64(usage)
		case snapshot.MetalCacheMemoryBytes != nil && snapshot.MetalPeakMemoryBytes != nil && *snapshot.MetalPeakMemoryBytes > 0:
			usage := float64(*snapshot.MetalCacheMemoryBytes) / float64(*snapshot.MetalPeakMemoryBytes)
			snapshot.CacheUsage = utilization.Float64(usage)
		}
	}

	if snapshot.NumRunning < 0 || snapshot.NumWaiting < 0 {
		return rapidMLXStatusSnapshot{}, fmt.Errorf("invalid negative running/waiting counts")
	}

	return snapshot, nil
}

type rapidMLXStatusSnapshot struct {
	NumRunning             int
	NumWaiting             int
	TotalPromptTokens      int
	TotalCompletionTokens  int
	CacheUsage             *float64
	CacheHitType           *string
	CachedTokens           *int
	GeneratedTokens        *int
	ActiveRequestPhase     *string
	TTFTSeconds            *float64
	TokensPerSecond        *float64
	MetalActiveMemoryBytes *int64
	MetalPeakMemoryBytes   *int64
	MetalCacheMemoryBytes  *int64
	ActiveRequests         []rapidMLXRequestSnapshot
	Raw                    map[string]any
}

type rapidMLXRequestSnapshot struct {
	Phase           *string
	CacheHitType    *string
	CachedTokens    *int
	GeneratedTokens *int
	TTFTSeconds     *float64
	TokensPerSecond *float64
}

func (s rapidMLXStatusSnapshot) normalize() utilization.EndpointUtilization {
	out := utilization.EndpointUtilization{
		ActiveRequests:         utilization.Int(s.NumRunning),
		QueuedRequests:         utilization.Int(s.NumWaiting),
		Source:                 utilization.SourceRapidMLXStatus,
		Freshness:              utilization.FreshnessUnknown,
		TotalPromptTokens:      utilization.Int(s.TotalPromptTokens),
		TotalCompletionTokens:  utilization.Int(s.TotalCompletionTokens),
		CacheHitType:           s.CacheHitType,
		CachedTokens:           s.CachedTokens,
		GeneratedTokens:        s.GeneratedTokens,
		ActiveRequestPhase:     s.ActiveRequestPhase,
		TTFTSeconds:            s.TTFTSeconds,
		TokensPerSecond:        s.TokensPerSecond,
		MetalActiveMemoryBytes: s.MetalActiveMemoryBytes,
		MetalPeakMemoryBytes:   s.MetalPeakMemoryBytes,
		MetalCacheMemoryBytes:  s.MetalCacheMemoryBytes,
	}
	if s.CacheUsage != nil {
		out.CacheUsage = utilization.Float64(*s.CacheUsage)
	}
	if out.ActiveRequestPhase == nil && len(s.ActiveRequests) > 0 {
		out.ActiveRequestPhase = s.ActiveRequests[0].Phase
	}
	return out
}

