107			if model, ok := firstMap(payload, "model", "loaded_model", "memory", "memory_stats"); ok {
108				if snapshot.ModelMemoryUsedBytes == nil {
109					snapshot.ModelMemoryUsedBytes = firstInt64(model, "used_bytes", "used", "memory_used_bytes", "active_bytes")
110				}
111				if snapshot.ModelMemoryMaxBytes == nil {
112					snapshot.ModelMemoryMaxBytes = firstInt64(model, "max_bytes", "max", "memory_max_bytes", "peak_bytes")
113				}
114			}
115		}
116	
117		return snapshot, nil
118	}
