225	func collectModelIDs(raw any) []string {
226		switch v := raw.(type) {
227		case []any:
228			ids := make([]string, 0, len(v))
229			for _, item := range v {
230				if id := modelIDFromValue(item); id != "" {
231					ids = append(ids, id)
232				}
233			}
234			return ids
235		case map[string]any:
236			if id := modelIDFromValue(v); id != "" {
237				return []string{id}
238			}
239		}
240		return nil
241	}
