243	func modelIDFromValue(raw any) string {
244		switch v := raw.(type) {
245		case string:
246			return strings.TrimSpace(v)
247		case map[string]any:
248			for _, key := range []string{"id", "name", "model", "model_id"} {
249				if value, ok := v[key].(string); ok && strings.TrimSpace(value) != "" {
250					return strings.TrimSpace(value)
251				}
252			}
253		}
254		return ""
255	}
